style.css:
/* Base Styling */
body {
    font-family: 'Orbitron', sans-serif !important;
    color: #ffffff !important;
    background-color: #000000 !important;
    text-shadow: 0 0 8px rgba(255, 0, 0, 0.8), 0 0 16px rgba(255, 0, 0, 0.6);
    line-height: 1.6 !important;
}

/* Links and Hover Effects */
a {
    color: #ff0000 !important; /* Bright red for links */
    text-decoration: none !important;
    transition: all 0.3s ease-in-out;
}

a:hover {
    color: #ffffff !important; /* Turn white on hover */
    background: linear-gradient(90deg, #ff0000, #ff4d4d);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    text-shadow: 0 0 16px rgba(255, 0, 0, 1), 0 0 32px rgba(255, 0, 0, 0.8);
}

/* Buttons */
button, input[type="button"], input[type="submit"] {
    font-family: 'Orbitron', sans-serif !important;
    background: #1a0000;
    color: #ff0000;
    border: 2px solid #ff0000;
    padding: 10px 20px;
    border-radius: 5px;
    transition: all 0.3s ease-in-out;
    cursor: pointer;
}

button:hover, input[type="button"]:hover, input[type="submit"]:hover {
    background: #ff0000;
    color: #ffffff;
    border-color: #ffffff;
    box-shadow: 0 0 12px rgba(255, 0, 0, 0.8), 0 0 24px rgba(255, 0, 0, 0.6);
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #ff0000 !important;
    text-shadow: 0 0 12px rgba(255, 0, 0, 0.8), 0 0 24px rgba(255, 0, 0, 0.6);
    font-weight: bold !important;
}

/* Form Inputs */
input, textarea {
    background: #1a0000 !important;
    color: #ffffff !important;
    border: 2px solid #ff0000 !important;
    border-radius: 5px;
    padding: 10px;
    transition: all 0.3s ease-in-out;
}

input:focus, textarea:focus {
    border-color: #ffffff !important;
    box-shadow: 0 0 12px rgba(255, 0, 0, 0.8), 0 0 24px rgba(255, 0, 0, 0.6);
    outline: none !important;
}

/* Smooth Animations */
* {
    transition: all 0.3s ease-in-out !important;
}

/* Bug Fix: Avoid Breaking Layouts */
img, video, iframe {
    max-width: 100% !important;
    height: auto !important;
    border: none !important;
}

table {
    border-collapse: collapse !important;
    width: 100% !important;
}

th, td {
    border: 1px solid #ff0000 !important;
    padding: 8px !important;
    text-align: left !important;
}

/* Scrollbar Customization */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-thumb {
    background: #ff0000;
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: #ff4d4d;
}

::-webkit-scrollbar-track {
    background: #1a0000;
}
